    dict(key="softly", name="Softly", category="IN TUNE WITH YOU", title="Your cycle.\nA little clearer.", description="A calm place to understand your cycle, record how you feel, and look ahead with a little more clarity.", label="Period & cycle tracker", features="Cycle calendar · Personal insights · Private by design"),
