def icon(key, name, extra=""):
    return f'<img class="app-icon {extra}" src="assets/{key}.webp" width="384" height="384" alt="{escape(name)} app icon" decoding="async">'

def illustration(key):
    if key == "oftenly":
        return '''<div class="visual habit-art" aria-hidden="true"><span class="art-sun">✳</span><div class="habit-window"><div class="window-greeting">A little better, every day.</div><div class="window-date">YOUR DAILY RHYTHM</div><div class="habit-row"><span class="habit-emoji">☀</span><span>Make time for yourself<small>A fresh start</small></span><span class="done">✓</span></div><div class="habit-row"><span class="habit-emoji">♧</span><span>Get some fresh air<small>A little goes a long way</small></span><span class="done">✓</span></div><div class="habit-row"><span class="habit-emoji">▤</span><span>Read a few pages<small>One page at a time</small></span><span class="empty-check"></span></div></div><div class="habit-note">Progress, at your pace.</div></div>'''
    if key == "softly":
        cells = ''.join(f'<span class="{"period-day" if 9 <= n <= 13 else ""}">{n}</span>' for n in range(1,29))
        return f'''<div class="visual cycle-art" aria-hidden="true"><span class="cycle-flower">✿</span><div class="calendar-window"><div class="calendar-heading">Your own rhythm.<span>♡</span></div><div class="calendar-caption">A LITTLE MORE IN TUNE</div><div class="weekdays"><span>M</span><span>T</span><span>W</span><span>T</span><span>F</span><span>S</span><span>S</span></div><div class="calendar-grid">{cells}</div><div class="calendar-key"><i></i> Your period, gently tracked</div></div><div class="cycle-note">Made for your rhythm.</div></div>'''
